if(!customElements.get("media-popup")){class e extends HTMLElement{constructor(){super(),this.init()}init(){document.querySelectorAll("[data-popup-trigger]").forEach(e=>{e.addEventListener("click",()=>{const t=e.dataset.popupTrigger,s=document.getElementById(t);s&&this.open(s)})});document.querySelectorAll(".popup-media__closer").forEach(e=>{e.addEventListener("click",()=>{const t=e.closest(".media__popup");t&&this.close(t)})}),document.addEventListener("click",e=>{if(e.target.classList.contains("media__popup")||e.target.classList.contains("media__popup-wrapper")){const t=e.target.closest(".media__popup");t&&!e.target.closest(".media__popup-container")&&this.close(t)}}),document.addEventListener("keyup",e=>{if("Escape"===e.key){const e=document.querySelector('.media__popup[style*="visibility: visible"]');e&&this.close(e)}})}open(e){document.body.classList.add("popup-open"),e.style.visibility="visible",e.style.opacity="1"}close(e){document.body.classList.remove("popup-open"),e.style.visibility="hidden",e.style.opacity="0"}}customElements.define("media-popup",e)}